declarations.type:
∀ (alpha_s alpha v_x v_y v_z Omega_x Omega_y Omega_z t_p_val : ℝ),
  AsymmetricTensor.U_hat alpha_s alpha v_x v_y v_z Omega_x Omega_y Omega_z t_p_val =
    Matrix.of fun i j =>
      if i = 0 ∧ j = 0 then -alpha_s ^ 2
      else
        if i = 0 ∧ j = 1 then -alpha * (v_x / AsymmetricTensor.c)
        else
          if i = 0 ∧ j = 2 then -alpha * (v_y / AsymmetricTensor.c)
          else
            if i = 0 ∧ j = 3 then -alpha * (v_z / AsymmetricTensor.c)
            else
              if i = 1 ∧ j = 0 then alpha * (v_x / AsymmetricTensor.c)
              else
                if i = 1 ∧ j = 1 then 1 / alpha_s ^ 2
                else
                  if i = 1 ∧ j = 2 then -alpha * (t_p_val * Omega_z)
                  else
                    if i = 1 ∧ j = 3 then alpha * (t_p_val * Omega_y)
                    else
                      if i = 2 ∧ j = 0 then alpha * (v_y / AsymmetricTensor.c)
                      else
                        if i = 2 ∧ j = 1 then alpha * (t_p_val * Omega_z)
                        else
                          if i = 2 ∧ j = 2 then 1 / alpha_s ^ 2
                          else
                            if i = 2 ∧ j = 3 then -alpha * (t_p_val * Omega_x)
                            else
                              if i = 3 ∧ j = 0 then alpha * (v_z / AsymmetricTensor.c)
                              else
                                if i = 3 ∧ j = 1 then -alpha * (t_p_val * Omega_y)
                                else
                                  if i = 3 ∧ j = 2 then alpha * (t_p_val * Omega_x)
                                  else if i = 3 ∧ j = 3 then 1 / alpha_s ^ 2 else 0
